-- ============================================================================
-- Correction contenu dupliqué (audit AdSense) : 478 fiches produit du catalogue
-- électronique importé (Soumari.com / Electromenager-Dakar.com / Promo.sn, cf.
-- sql/2026_08_25_catalogue_electronique_senegal.sql) avaient une description
-- copiée verbatim du site source, avec en plus la mention "Prix catalogue
-- X.com (marge appliquée)" laissée visible publiquement sur la fiche produit.
--
-- Ce script remplace les 478 descriptions par du contenu 100% original, généré
-- à partir du VRAI type de produit détecté par mots-clés dans le nom. Plusieurs
-- variantes de formulation par type de produit (rotation déterministe par id).
-- Aucune mention de site tiers, de "catalogue" ni de texte copié d'ailleurs.
--
-- v2 : remplace le pattern "table temporaire + UPDATE...FROM" (2 instructions
-- séparées) par un UNIQUE UPDATE...FROM (VALUES...) — le pooler Supabase peut
-- exécuter des instructions top-level séparées sur des connexions différentes,
-- ce qui faisait disparaître la table temporaire avant le UPDATE suivant
-- ("relation does not exist"). Une seule instruction = pas de ce problème.
--
-- Ne touche à AUCUNE autre colonne (name/category/price/vendor_id... inchangés)
-- et ne modifie aucune fiche produit en dehors de ces 478 id.
-- ============================================================================

-- 1) Filet de sécurité : purge toute mention résiduelle du motif "Prix
--    catalogue ... (...)" où qu'elle traîne encore (idempotent).
update public.products
set description = regexp_replace(description, '\s*Prix catalogue [^.(]*\([^)]*\)\.?', '', 'gi')
where description ~* 'Prix catalogue';

-- 2) Remplacement des 478 descriptions dupliquées par du contenu original.
update public.products p
set description = v.description
from (values
